const updateClaimPaymentStatus = `-- name: UpdateClaimPaymentStatus :one

UPDATE claims
SET
    payment_status = $2,
    confirmed_at   = COALESCE($3, confirmed_at),
    updated_at     = NOW()
WHERE id = $1
RETURNING id, listing_id, buyer_id, quantity, payment_status, pickup_status, stripe_payment_intent_id, reserved_at, confirmed_at, rating, rated_at, created_at, updated_at
`

type UpdateClaimPaymentStatusParams struct {
	ID            pgtype.UUID        `json:"id"`
	PaymentStatus ClaimPaymentStatus `json:"payment_status"`
	ConfirmedAt   pgtype.Timestamptz `json:"confirmed_at"`
}

// ============================================================
// UpdateClaimPaymentStatus
// ============================================================
// Transitions the payment_status of a claim. The confirmed_at column is set when
// the new status is 'paid'; otherwise it is left unchanged (NULL coalesce preserves
// the existing value).
//
// Parameters:
//
//	$1 id               UUID
//	$2 payment_status   claim_payment_status
//	$3 confirmed_at     TIMESTAMPTZ  — pass NOW() on 'paid', NULL on other transitions
func (q *Queries) UpdateClaimPaymentStatus(ctx context.Context, arg UpdateClaimPaymentStatusParams) (Claim, error) {
	row := q.db.QueryRow(ctx, updateClaimPaymentStatus, arg.ID, arg.PaymentStatus, arg.ConfirmedAt)
	var i Claim
	err := row.Scan(
		&i.ID,
		&i.ListingID,
		&i.BuyerID,
		&i.Quantity,
		&i.PaymentStatus,
		&i.PickupStatus,
		&i.StripePaymentIntentID,
		&i.ReservedAt,
		&i.ConfirmedAt,
		&i.Rating,
		&i.RatedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
